import java.util.Random;
import java.util.ArrayList;
import java.util.List;

public class analyze_random {
    static class RandomInstance {
        Random random;
        long timestamp;
        List<Integer> numbers;

        public RandomInstance() {
            this.random = new Random();
            this.timestamp = System.currentTimeMillis();
            this.numbers = new ArrayList<>();
            for (int i = 0; i < 5; i++) {
                numbers.add(this.random.nextInt());
            }
        }

        @Override
        public String toString() {
            return String.format("Timestamp: %d\nFirst 5 numbers: %s\n", 
                               timestamp, numbers.toString());
        }
    }

    public static void main(String[] args) {
        List<RandomInstance> instances = new ArrayList<>();

        // Create 10 Random instances in quick succession
        for (int i = 0; i < 10; i++) {
            instances.add(new RandomInstance());
            try {
                Thread.sleep(1); // Small delay to see timestamp differences
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        // Print results and analyze patterns
        for (int i = 0; i < instances.size(); i++) {
            System.out.println("Instance " + i + ":");
            System.out.println(instances.get(i));

            if (i > 0) {
                System.out.println("Time difference from previous: " + 
                    (instances.get(i).timestamp - instances.get(i-1).timestamp) + "ms");

                // Compare first numbers with previous instance
                System.out.println("Difference in first numbers: " + 
                    (instances.get(i).numbers.get(0) - instances.get(i-1).numbers.get(0)));
                System.out.println();
            }
        }
    }
}

import java.io.*;
import java.net.*;
import java.util.Random;

public class sync_random {
    public static void main(String[] args) {
        try {
            // Record connection time
            long connectionTime = System.currentTimeMillis();
            System.out.println("Connection time: " + connectionTime);

            // Connect to server
            Socket socket = new Socket("rev.chal.csaw.io", 4200);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);

            // Read initial server output and collect sequence
            String line;
            int[] serverSequence = new int[5];  // Store first 5 numbers
            int seqIndex = 0;

            while ((line = in.readLine()) != null && seqIndex < 5) {
                System.out.println("Server: " + line);
                if (line.contains("Result:")) {
                    try {
                        String numStr = line.substring(line.indexOf(":") + 1).trim();
                        serverSequence[seqIndex++] = Integer.parseInt(numStr);
                    } catch (NumberFormatException e) {
                        continue;
                    }
                }
                if (seqIndex < 5) {
                    out.println("1");  // Bet minimum amount to get next number
                }
            }

            System.out.println("\nServer sequence:");
            for (int i = 0; i < seqIndex; i++) {
                System.out.println(serverSequence[i]);
            }

            // Try different time offsets
            System.out.println("\nTrying to match sequence...");
            long startTime = connectionTime - 5000;  // Start 5 seconds before
            long endTime = connectionTime + 5000;    // End 5 seconds after

            for (long testTime = startTime; testTime <= endTime; testTime++) {
                Random random = new Random(testTime);
                boolean matches = true;

                for (int i = 0; i < seqIndex; i++) {
                    int bound = 37;  // Roulette numbers are 0-36
                    int generated = random.nextInt(bound);
                    if (generated != serverSequence[i]) {
                        matches = false;
                        break;
                    }
                }

                if (matches) {
                    System.out.println("Potential match found!");
                    System.out.println("Seed time: " + testTime);
                    System.out.println("Offset from connection: " + (testTime - connectionTime) + "ms");
                    System.out.println("Next 5 numbers in sequence:");
                    for (int i = 0; i < 5; i++) {
                        System.out.println(random.nextInt(37));
                    }
                    System.out.println();
                }
            }

            socket.close();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

