import java.io.*;
import java.net.*;
import java.util.Random;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.*;

public class sync_random {
    public static void main(String[] args) {
        try {
            // Record connection time
            long connectionTime = System.currentTimeMillis();
            System.out.println("Connection time: " + connectionTime);

            // Connect to server
            Socket socket = new Socket("rev.chal.csaw.io", 4200);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);

            // Read initial server output
            String line;
            List<Integer> serverSequence = new ArrayList<>();
            Pattern resultPattern = Pattern.compile("Result: (\\d+)");

            // Skip welcome messages
            while ((line = in.readLine()) != null) {
                System.out.println("Server: " + line);
                if (line.contains("How much do you want to bet?")) {
                    break;
                }
            }

            // Get first 5 rolls
            for (int i = 0; i < 5; i++) {
                // Place bet
                out.println("1");
                // Read bet confirmation
                while ((line = in.readLine()) != null) {
                    System.out.println("Server: " + line);
                    if (line.contains("color do you want to bet?"))
                        break;
                }

                out.println("red");

                // Read until we get a result
                boolean foundResult = false;
                while ((line = in.readLine()) != null && !foundResult) {
                    System.out.println("Server: " + line);
                    Matcher m = resultPattern.matcher(line);
                    if (m.find()) {
                        int number = Integer.parseInt(m.group(1));
                        serverSequence.add(number);
                        foundResult = true;
                        System.out.println("Found result: " + number);
                    }
                    if (line.contains("How much do you want to bet?")) {
                        break;
                    }
                }
            }

            System.out.println("\nCollected sequence:");
            for (Integer num : serverSequence) {
                System.out.println(num);
            }

            // Try different time offsets
            System.out.println("\nTrying to match sequence...");
            long startTime = connectionTime - 10000;  // Start 10 seconds before
            long endTime = connectionTime + 10000;    // End 10 seconds after

            for (long testTime = startTime; testTime <= endTime; testTime++) {
                Random random = new Random(testTime);
                boolean matches = true;

                for (int i = 0; i < serverSequence.size(); i++) {
                    if (random.nextInt(37) != serverSequence.get(i)) {
                        matches = false;
                        break;
                    }
                }

                if (matches) {
                    System.out.println("Potential match found!");
                    System.out.println("Seed time: " + testTime);
                    System.out.println("Offset from connection: " + (testTime - connectionTime) + "ms");

                    // Reset RNG to this seed and print next 20 numbers
                    random = new Random(testTime);
                    // Skip the numbers we already matched
                    for (int i = 0; i < serverSequence.size(); i++) {
                        random.nextInt(37);
                    }
                    // Print next 20 predicted numbers
                    System.out.println("Next 20 numbers:");
                    for (int i = 0; i < 20; i++) {
                        int next = random.nextInt(37);
                        System.out.println(next + " -> " + (next == 0 ? "green" : (next % 2 == 0 ? "black" : "red")));
                    }
                }
            }

            socket.close();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.net.*;
import java.util.*;

public class win_roulette {
    private static final String HOST = "rev.chal.csaw.io";
    private static final int PORT = 4200;
    private static final long SEED = System.currentTimeMillis();
    private static Random random;
    private static int greenWins = 0;
    private static double balance = 100.0; // Starting balance

    public static void main(String[] args) {
        try {
            Socket socket = new Socket(HOST, PORT);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            random = new Random(SEED);

            // Initial connection setup
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println("Server: " + line);

                if (line.contains("Enter your bet amount")) {
                    // Predict next number
                    int nextNumber = random.nextInt(37);
                    System.out.println("Predicted number: " + nextNumber);

                    // Betting strategy
                    double betAmount;
                    if (nextNumber == 0) { // If green (0) is predicted
                        betAmount = Math.min(balance, 10.0); // Bet more on green
                        System.out.println("Green predicted! Betting: $" + betAmount);
                    } else {
                        betAmount = 1.0; // Minimum bet otherwise
                        System.out.println("Regular number predicted. Minimum bet: $" + betAmount);
                    }

                    out.println(String.format("%.2f", betAmount));

                } else if (line.contains("Choose a number")) {
                    int prediction = random.nextInt(37);
                    System.out.println("Betting on number: " + prediction);
                    out.println(prediction);

                } else if (line.contains("landed on green")) {
                    greenWins++;
                    System.out.println("GREEN WIN! Total green wins: " + greenWins);

                } else if (line.contains("Current balance:")) {
                    try {
                        balance = Double.parseDouble(line.split("\\$")[1].trim());
                    } catch (Exception e) {
                        System.out.println("Error parsing balance: " + e.getMessage());
                    }
                    System.out.println("Current balance: $" + balance);

                } else if (line.contains("flag{")) {
                    System.out.println("FLAG FOUND: " + line);
                    socket.close();
                    return;
                }

                // Check if we've reached the target green wins
                if (greenWins >= 20) {
                    System.out.println("Reached target green wins!");
                }
            }

            socket.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.net.*;
import java.util.*;

public class win_roulette {
    private static final String HOST = "rev.chal.csaw.io";
    private static final int PORT = 4200;
    private static Random random;
    private static int greenWins = 0;
    private static double balance = 50.0; // Starting balance is $50

    public static void main(String[] args) {
        try {
            Socket socket = new Socket(HOST, PORT);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);

            // Initialize random with same seed as server
            random = new Random(System.currentTimeMillis() & 0xFFFF);

            String line;
            while ((line = in.readLine()) != null) {
                System.out.println("Server: " + line);

                if (line.contains("want to bet")) {
                    // Predict next number
                    int nextNumber = random.nextInt(37);
                    System.out.println("Predicted number: " + nextNumber);

                    // Aggressive betting strategy
                    double betAmount;
                    if (nextNumber == 0) { // If green (0) is predicted
                        betAmount = Math.max(1.0, balance * 0.5); // Bet 50% on green
                    } else {
                        betAmount = 1.0; // Minimum bet otherwise
                    }

                    System.out.printf("Betting $%.2f on %d%n", betAmount, nextNumber);
                    out.println(String.format("%.2f", betAmount));

                } else if (line.contains("Choose a number")) {
                    int prediction = random.nextInt(37);
                    System.out.println("Betting on: " + prediction);
                    out.println(prediction);

                } else if (line.contains("0 (green)")) {
                    greenWins++;
                    System.out.println("GREEN WIN! Total green wins: " + greenWins);

                } else if (line.contains("Current balance") || line.contains("have:")) {
                    try {
                        String[] parts = line.split("\\$");
                        if (parts.length > 1) {
                            balance = Double.parseDouble(parts[1].split(" ")[0].trim());
                            System.out.println("Balance updated: $" + balance);
                        }
                    } catch (Exception e) {
                        System.out.println("Error parsing balance: " + e.getMessage());
                    }
                } else if (line.contains("flag{")) {
                    System.out.println("FLAG FOUND: " + line);
                    socket.close();
                    return;
                }

                if (line.contains("Game Over") || line.contains("Insufficient") || balance < 1.0) {
                    System.out.println("Game ended. Restarting...");
                    socket.close();
                    main(args); // Restart the game
                    return;
                }
            }

            socket.close();
        } catch (Exception e) {
            System.out.println("Error occurred: " + e.getMessage());
            // Retry on error
            try {
                Thread.sleep(1000);
                main(args);
            } catch (InterruptedException ie) {}
        }
    }
}

