import java.io.*;
import java.net.*;
import java.util.*;
import java.time.*;
import java.time.temporal.ChronoUnit;

public class win_roulette {
    private static final String HOST = "rev.chal.csaw.io";
    private static final int PORT = 4200;
    private static final int TARGET_WINS = 20;
    private static final int SEED_WINDOW = 5000; // Wider window for seed search
    private static final int PARALLEL_TESTS = 3;
    private static final double MIN_BET = 1.0;
    private static final double TEST_BET = 1.0;

    static class GameState {
        double balance;
        int greenWins;
        int roundsPlayed;
        long predictedSeed;
        boolean seedConfirmed;
        int consecutiveCorrect;
        List<Integer> sequence;

        public GameState() {
            this.balance = 50.0;
            this.greenWins = 0;
            this.roundsPlayed = 0;
            this.seedConfirmed = false;
            this.consecutiveCorrect = 0;
            this.sequence = new ArrayList<>();
        }
    }

    public static void main(String[] args) {
        try {
            // Get accurate time using multiple requests
            long avgOffset = syncTimeWithServer();
            long baseTime = System.currentTimeMillis() + avgOffset;

            // Create seed ranges for parallel testing
            List<SeedRange> seedRanges = createSeedRanges(baseTime);

            // Try seeds in parallel
            for (SeedRange range : seedRanges) {
                if (testSeedRange(range)) {
                    return; // Success - flag found
                }
            }

            System.out.println("All seed ranges exhausted without finding flag");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static long syncTimeWithServer() throws Exception {
        long totalOffset = 0;
        int successfulSyncs = 0;

        // Multiple sync attempts for better accuracy
        for (int i = 0; i < 5; i++) {
            try {
                long beforeConnect = System.currentTimeMillis();
                Socket socket = new Socket(HOST, PORT);
                long afterConnect = System.currentTimeMillis();
                socket.close();

                long roundTripTime = afterConnect - beforeConnect;
                long estimatedServerTime = beforeConnect + (roundTripTime / 2);
                totalOffset += (estimatedServerTime - beforeConnect);
                successfulSyncs++;

                Thread.sleep(100); // Brief pause between syncs
            } catch (Exception e) {
                System.out.println("Sync attempt " + i + " failed");
            }
        }

        return successfulSyncs > 0 ? totalOffset / successfulSyncs : 0;
    }

    static class SeedRange {
        long start;
        long end;

        SeedRange(long start, long end) {
            this.start = start;
            this.end = end;
        }
    }

    private static List<SeedRange> createSeedRanges(long baseTime) {
        List<SeedRange> ranges = new ArrayList<>();
        long baseSeed = (baseTime / 100) & 0xFFFF;

        // Forward ranges
        ranges.add(new SeedRange(baseSeed, baseSeed + SEED_WINDOW));
        // Backward ranges
        ranges.add(new SeedRange(baseSeed - SEED_WINDOW, baseSeed));
        // Extended range
        ranges.add(new SeedRange(baseSeed + SEED_WINDOW, baseSeed + (SEED_WINDOW * 2)));

        return ranges;
    }

    private static boolean testSeedRange(SeedRange range) {
        for (long seed = range.start; seed < range.end; seed++) {
            System.out.println("Testing seed: " + seed);
            if (attemptGame(seed)) {
                return true;
            }
            try {
                Thread.sleep(1);
            } catch (InterruptedException e) {}
        }
        return false;
    }

    private static boolean attemptGame(long seed) {
        Socket socket = null;
        try {
            socket = new Socket(HOST, PORT);
            socket.setSoTimeout(5000);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);

            GameState state = new GameState();
            initializeSequence(state, seed);

            String line;
            while ((line = in.readLine()) != null) {
                if (line.contains("flag{")) {
                    System.out.println("FLAG FOUND: " + line);
                    return true;
                }

                if (processGameLine(line, out, state)) {
                    return false; // Game ended
                }
            }
        } catch (Exception e) {
            System.out.println("Error in game: " + e.getMessage());
        } finally {
            try {
                if (socket != null) socket.close();
            } catch (IOException e) {}
        }
        return false;
    }

    private static void initializeSequence(GameState state, long seed) {
        Random random = new Random(seed);
        state.predictedSeed = seed;
        state.sequence.clear();

        // Generate longer sequence for validation
        for (int i = 0; i < 200; i++) {
            state.sequence.add(random.nextInt(37));
        }
    }

    private static boolean processGameLine(String line, PrintWriter out, GameState state) {
        // Handle betting
        if (line.contains("How much do you want to bet?")) {
            return handleBetting(out, state);
        }
        // Handle color selection
        else if (line.contains("(red/black/green)")) {
            out.println("green");
        }
        // Track wins and validate predictions
        else if (line.contains("color was green")) {
            handleWin(state);
        }
        // Update balance
        else if (line.contains("You have:") && line.contains("dollars")) {
            updateBalance(line, state);
        }
        // Check game over conditions
        else if (line.contains("Game Over") || line.contains("Insufficient") || state.balance <= 0) {
            return true;
        }
        // Track rounds
        else if (line.contains("The color was")) {
            state.roundsPlayed++;
        }

        return false;
    }

    private static boolean handleBetting(PrintWriter out, GameState state) {
        int nextNumber = state.sequence.get(state.roundsPlayed % state.sequence.size());
        double betAmount;

        if (!state.seedConfirmed) {
            // Using minimum bets until seed is confirmed
            betAmount = TEST_BET;
        } else if (nextNumber == 0) {
            // Optimized betting for confirmed green
            betAmount = calculateOptimalBet(state);
        } else {
            betAmount = MIN_BET;
        }

        System.out.printf("Round %d: Number %d predicted, betting $%.2f (Balance: $%.2f, Wins: %d)%n",
            state.roundsPlayed, nextNumber, betAmount, state.balance, state.greenWins);

        out.println(String.format("%.2f", betAmount));
        state.balance -= betAmount;

        return false;
    }

    private static void handleWin(GameState state) {
        state.greenWins++;
        state.consecutiveCorrect++;

        if (state.consecutiveCorrect >= 3) {
            state.seedConfirmed = true;
        }

        System.out.printf("GREEN WIN! Wins: %d/%d, Consecutive: %d%n",
            state.greenWins, TARGET_WINS, state.consecutiveCorrect);
    }

    private static void updateBalance(String line, GameState state) {
        try {
            state.balance = Double.parseDouble(line.replaceAll("[^0-9.]", ""));
        } catch (NumberFormatException e) {
            state.balance = 0;
        }
    }

    private static double calculateOptimalBet(GameState state) {
        // Keep some reserve for future bets
        double reserveRatio = 0.2;
        double availableBalance = state.balance * (1 - reserveRatio);

        // Calculate optimal bet size based on remaining wins needed
        int remainingWins = TARGET_WINS - state.greenWins;
        if (remainingWins <= 0) return MIN_BET;

        // More aggressive betting as we get closer to target
        double betRatio = 1.0 / remainingWins;
        double optimalBet = availableBalance * betRatio;

        // Ensure bet is at least minimum and doesn't exceed balance
        return Math.max(MIN_BET, Math.min(optimalBet, state.balance - 1));
    }
}

