    private long balance = 100;
    private int consecutiveWins = 0;

    public roulette_final() {
        possibleSeeds = new ArrayList<>();
        seedProbabilities = new ConcurrentHashMap<>();
        baseTimestamp = System.currentTimeMillis();
    }

    private void connect() throws IOException {
        socket = new Socket(HOST, PORT);
        socket.setTcpNoDelay(true);
        in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        out = new PrintWriter(socket.getOutputStream(), true);
    }

    private void updateTimingStats(long startTime) {
        long rtt = System.currentTimeMillis() - startTime;
        avgRTT = (avgRTT == 0) ? rtt : (avgRTT * 0.9 + rtt * 0.1);
        timeDrift = (System.currentTimeMillis() - baseTimestamp) % 1000;
    }

    private void initializeSeedPool() {
        long currentTime = System.currentTimeMillis();
        for (long i = currentTime - 5000; i <= currentTime + 5000; i++) {
            possibleSeeds.add(i);
            seedProbabilities.put(i, 1.0);
        }
    }

    private int predictNextNumber(long seed) {
        Random r = new Random(seed);
        // Simulate the server's RNG sequence
        r.nextInt(); // gambler IP
        r.nextInt(); // gambler count
        r.nextInt(); // betting amount
        r.nextBoolean(); // won state
        return r.nextInt(37); // winning number
    }

    private void updateProbabilities(int observedNumber) {
        Iterator<Long> iterator = possibleSeeds.iterator();
        while (iterator.hasNext()) {
            long seed = iterator.next();
            int predicted = predictNextNumber(seed);
            if (predicted == observedNumber) {
                seedProbabilities.put(seed, seedProbabilities.get(seed) * 1.5);
            } else {
                iterator.remove();
                seedProbabilities.remove(seed);
            }
        }
    }

    private double calculateKellyCriterion(double probability, double odds) {
        return (probability * (odds + 1) - 1) / odds;
    }

    private String getBestBet() {
        if (possibleSeeds.isEmpty()) return null;

        long bestSeed = possibleSeeds.get(0);
        double maxProb = seedProbabilities.get(bestSeed);

        for (long seed : possibleSeeds) {
            if (seedProbabilities.get(seed) > maxProb) {
                maxProb = seedProbabilities.get(seed);
                bestSeed = seed;
            }
        }

        int predictedNumber = predictNextNumber(bestSeed);
        return predictedNumber <= 18 ? "black" : "red";
    }

    private void placeBet() throws IOException {
        // Read banner and initial stats
        for (int i = 0; i < 4; i++) in.readLine();

        String bestBet = getBestBet();
        int betAmount = (int)(balance * 0.1); // Conservative betting

