        out.println(bestBet != null ? bestBet : "black");

        // Process result
        String result = in.readLine();
        if (result.contains("Congratulations")) {
            consecutiveWins++;
            balance += betAmount;
        } else {
            consecutiveWins = 0;
            balance -= betAmount;
        }

        // Update timing and probabilities
        String winningLine = in.readLine();
        if (winningLine.contains("Winning number")) {
            int winningNumber = Integer.parseInt(winningLine.replaceAll("\\D+", ""));
            updateProbabilities(winningNumber);
        }

        // Check for flag
        if (consecutiveWins >= 3) {
            String line;
            while ((line = in.readLine()) != null) {
                if (line.contains("flag{")) {
                    System.out.println("Found flag: " + line);
                    break;
                }
            }
        }
    }

    public void execute() {
        try {
            connect();
            initializeSeedPool();

            while (balance > 0 && consecutiveWins < 3) {
                long startTime = System.currentTimeMillis();
                placeBet();
                updateTimingStats(startTime);

                if (possibleSeeds.size() < 10) {
