    return remote('rev.chal.csaw.io', 4200)

def get_three_numbers(conn):
    numbers = []
    conn.recvuntil(b"Welcome to the Roulette!")
    for _ in range(3):
        conn.recvuntil(b"Number: ")
        num = int(conn.recvline().strip())
        numbers.append(num)
        log.info(f"Got number: {num}")
    return numbers

def find_seed_and_greens(timestamp, nums):
    result = subprocess.run(['java', 'RouletteSimple', str(timestamp)] + [str(n) for n in nums], 
                          capture_output=True, text=True)

    seed_line = None
    green_positions = []

    for line in result.stdout.splitlines():
        if line.startswith('SEED_FOUND:'):
            seed_line = int(line.split(':')[1])
        elif line.startswith('GREEN_AT:'):
            green_positions.append(int(line.split(':')[1]))

    return seed_line, green_positions

def execute_betting_strategy(conn, green_positions):
    balance = 100  # Starting balance
    current_pos = 0

    while True:
        if current_pos in green_positions:
            bet_amount = min(balance, 100)  # Bet up to 100 chips on green
            conn.sendline(f"bet {bet_amount} 0".encode())
            response = conn.recvuntil(b"Balance: ").decode()
            new_balance = int(conn.recvline().strip())

            if "won" in response.lower():
                balance = new_balance
                log.info(f"Won bet! New balance: {balance}")

                if balance >= 100000:
                    log.success("Reached target balance!")
                    return True

        else:
            # Skip this round with minimum bet on a random number
            conn.sendline(b"bet 1 1")
            conn.recvuntil(b"Balance: ")
            balance = int(conn.recvline().strip())

        current_pos += 1
        if current_pos >= max(green_positions):
            break

    return False

def main():
