        compile_java()
        log.info("Java code compiled successfully")

        conn = connect_to_server()
        connection_time = int(time.time() * 1000)
        log.info(f"Connected at: {connection_time}")

        numbers = get_three_numbers(conn)
        log.info(f"Got numbers: {numbers}")

        seed, green_positions = find_seed_and_greens(connection_time, numbers)

        if not seed:
            log.error("No matching seed found")
            return

        log.success(f"Found matching seed: {seed}")
        log.info(f"Green positions: {green_positions}")

        success = execute_betting_strategy(conn, green_positions)

        if success:
            # Try to get flag
            final_output = conn.recvall().decode()
            if 'flag{' in final_output:
                flag = re.findall(r'flag{[^}]+}', final_output)[0]
                log.success(f"Found flag: {flag}")

    except Exception as e:
        log.error(f"Error: {str(e)}")
    finally:
        if conn:
            conn.close()

if __name__ == "__main__":
    main()

import java.util.Random;
