public class RouletteSimple {
    private static final int[] ALL_NUMBERS = {
        0, 32, 15, 19, 4, 21, 2, 25, 17, 34, 6, 27, 13, 36, 11, 30, 8, 23, 10, 5, 24, 16, 33,
        1, 20, 14, 31, 9, 22, 18, 29, 7, 28, 12, 35, 3, 26
    };

    private static boolean matchesNumbers(Random random, int[] targetNumbers) {
        for (int i = 0; i < targetNumbers.length; i++) {
            if (ALL_NUMBERS[random.nextInt(ALL_NUMBERS.length)] != targetNumbers[i]) {
                return false;
            }
        }
        return true;
    }

    private static List<Integer> findGreenPositions(Random random, int count) {
        List<Integer> positions = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            if (ALL_NUMBERS[random.nextInt(ALL_NUMBERS.length)] == 0) {
                positions.add(i);
            }
        }
        return positions;
    }

    public static void main(String[] args) {
        if (args.length < 4) {
            System.err.println("Usage: java RouletteSimple <timestamp> <num1> <num2> <num3>");
            return;
        }

        long baseTimestamp = Long.parseLong(args[0]);
        int[] targetNumbers = new int[3];
        for (int i = 0; i < 3; i++) {
            targetNumbers[i] = Integer.parseInt(args[i + 1]);
        }

        // Search 5 seconds before and after the timestamp
        for (long offset = -5000; offset <= 5000; offset++) {
            long testTimestamp = baseTimestamp + offset;
            Random random = new Random(testTimestamp);

            if (matchesNumbers(random, targetNumbers)) {
                System.out.println("SEED_FOUND:" + testTimestamp);

                // Reset random with found seed and skip the first 3 numbers
                random = new Random(testTimestamp);
                for (int i = 0; i < 3; i++) {
                    random.nextInt(ALL_NUMBERS.length);
                }

                // Find next 100 positions where green (0) appears
                List<Integer> greenPositions = findGreenPositions(random, 100);
                for (int pos : greenPositions) {
                    System.out.println("GREEN_AT:" + pos);
                }
                return;
            }
        }
    }
}

