    conn.recvuntil(b"Number: ")
    num3 = int(conn.recvline().strip())
    numbers.append(num3)

    return numbers

def find_seed_and_greens(timestamp, nums):
    cmd = ['java', 'RouletteSimple', str(timestamp)] + [str(n) for n in nums]
    result = subprocess.run(cmd, capture_output=True, text=True)

    seed_line = None
    green_positions = []

    for line in result.stdout.splitlines():
        if line.startswith('SEED_FOUND:'):
            seed_line = int(line.split(':')[1])
        elif line.startswith('GREEN_AT:'):
            green_positions.append(int(line.split(':')[1]))

    return seed_line, green_positions

def execute_betting_strategy(conn, green_positions):
    balance = 47  # After 3 bets of 1, we have 47 left
    green_count = 0

    for pos in range(100):
        conn.recvuntil(b"How much do you want to bet?")

        if pos in green_positions:
            bet_amount = min(balance, 10)  # Conservative betting
            log.info(f"Betting {bet_amount} on green")
            conn.sendline(str(bet_amount).encode())
            conn.recvuntil(b"What color do you want to bet? (red/black/green)")
            conn.sendline(b"green")

            resp = conn.recvuntil(b"You have: ")
            balance = int(conn.recvline().strip().split()[0])

            if b"won" in resp.lower():
                green_count += 1
                log.success(f"Won on green! Balance: {balance}, Green wins: {green_count}")

                if green_count >= 20:
                    log.success("Got 20 greens!")
                    return True
        else:
            # Minimum bet on red to keep playing
            conn.sendline(b"1")
            conn.recvuntil(b"What color do you want to bet? (red/black/green)")
            conn.sendline(b"red")
            conn.recvuntil(b"You have: ")
            balance = int(conn.recvline().strip().split()[0])

        if balance <= 0:
            log.error("Out of money!")
            return False

    return False

