            // Test first three numbers
            int test1 = rng.nextInt(35);
            int test2 = rng.nextInt(35);
            int test3 = rng.nextInt(35);

            if (test1 == num1 && test2 == num2 && test3 == num3) {
                System.out.println("SEED_FOUND:" + testTimestamp);

                // Reset RNG to start
                rng = new Random(testTimestamp);
                rng.nextInt(35); // skip first 3 numbers
                rng.nextInt(35);
                rng.nextInt(35);

                // Predict next 100 numbers
                for (int i = 0; i < 100; i++) {
                    int next = rng.nextInt(35);
                    if (next == 0) {  // 0 is green
                        System.out.println("GREEN_AT:" + i);
